ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    int data_available;

    spin_lock(&sound_timer_spinlock);
    mutex_lock(&sound_timer_mutex);

    while ((data_available = sound_timer_data_available()) <= 0) {
        if (file->f_flags & O_NONBLOCK) {
            mutex_unlock(&sound_timer_mutex);
            spin_unlock(&sound_timer_spinlock);
            return -EAGAIN;
        }

        if (signal_pending(current)) {
            mutex_unlock(&sound_timer_mutex);
            spin_unlock(&sound_timer_spinlock);
            return -ERESTARTSYS;
        }

        wait_for_sound_timer_data();
    }

    while (bytes_read < count && sound_timer_data_available() > 0) {
        ssize_t chunk = min(sound_timer_data_available(), count - bytes_read);
        ssize_t copied = copy_to_user(buffer + bytes_read, sound_timer_peek(), chunk);
        if (copied != 0) {
            mutex_unlock(&sound_timer_mutex);
            spin_unlock(&sound_timer_spinlock);
            return -EFAULT;
        }

        sound_timer_consume(chunk);
        bytes_read += chunk;
        *offset += chunk;
    }

    mutex_unlock(&sound_timer_mutex);
    spin_unlock(&sound_timer_spinlock);

    return bytes_read;
}

ssize_t read_sound_timer_data(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;

    // Acquire the device's mutex for thread-safe access
    mutex_lock(&sound_timer_mutex);

    // Acquire the spinlock for synchronized data access
    spin_lock(&sound_timer_spinlock);

    // Check if there is data available in the queue
    if (sound_timer_queue_empty()) {
        // Wait for data to become available (non-blocking or interruptible)
        if (wait_for_data() < 0) {
            // Handle error or interruption
            spin_unlock(&sound_timer_spinlock);
            mutex_unlock(&sound_timer_mutex);
            return -ERESTARTSYS;
        }
    }

    // Read available data from the queue into the user buffer
    while (bytes_read < count && !sound_timer_queue_empty()) {
        char data = dequeue_sound_timer_data();
        if (copy_to_user(buffer + bytes_read, &data, 1) != 0) {
            spin_unlock(&sound_timer_spinlock);
            mutex_unlock(&sound_timer_mutex);
            return -EFAULT;
        }
        bytes_read += 1;
    }

    // Update the read offset
    *offset += bytes_read;

    // Release the spinlock and mutex
    spin_unlock(&sound_timer_spinlock);
    mutex_unlock(&sound_timer_mutex);

    return bytes_read;
}

ssize_t read_sound_timer(struct file *file, char __user *buffer, size_t count, loff_t *offset)
{
    ssize_t bytes_read = 0;
    int ret;

    spin_lock(&device_spinlock);
    mutex_lock(&device_mutex);

    while (device_queue_empty()) {
        if (file->f_flags & O_NONBLOCK) {
            ret = -EAGAIN;
            goto error_unlock;
        }

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto error_unlock;
        }

        wait_event_interruptible(device_wait_queue, !device_queue_empty());
    }

    while (bytes_read < count && !device_queue_empty()) {
        char data = device_peek();
        if (copy_to_user(buffer + bytes_read, &data, 1)) {
            ret = -EFAULT;
            goto error_unlock;
        }
        bytes_read += 1;
        device_dequeue();
    }

    *offset += bytes_read;
    mutex_unlock(&device_mutex);
    spin_unlock(&device_spinlock);
    return bytes_read;

error_unlock:
    mutex_unlock(&device_mutex);
    spin_unlock(&device_spinlock);
    return ret;
}

ssize_t sound_timer_read(struct file *file, char __user *buffer, size_t count, loff_t *offset) {
    ssize_t bytes_read = 0;
    int ret;

    spin_lock(&device->spinlock);
    mutex_lock(&device->mutex);

    while (device->queue_size == 0) {
        if (file->f_flags & O_NONBLOCK) {
            ret = -EAGAIN;
            goto out;
        }

        if (signal_pending(current)) {
            ret = -ERESTARTSYS;
            goto out;
        }

        wait_event_interruptible(device->read_wait_queue, device->queue_size > 0);
    }

    bytes_read = min(count, (size_t)device->queue_size);
    if (copy_to_user(buffer, device->queue + device->read_pos, bytes_read)) {
        ret = -EFAULT;
        goto out;
    }

    device->read_pos = (device->read_pos + bytes_read) % DEVICE_BUFFER_SIZE;
    device->queue_size -= bytes_read;
    *offset += bytes_read;

out:
    mutex_unlock(&device->mutex);
    spin_unlock(&device->spinlock);

    if (ret < 0) {
        return ret;
    }

    return bytes_read;
}

